import csv
import io
import re
from typing import List, Dict, Union


def _read_records(raw_csv: str) -> List[List[str]]:
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    try:
        return [
            list(record)
            for record in csv.reader(
                stream,
                delimiter=",",
                quotechar='"',
                doublequote=True,
                skipinitialspace=False,
                strict=False,
            )
        ]
    except csv.Error:
        records: List[List[str]] = []
        lines = raw_csv.splitlines(keepends=True)
        buffer = ""

        for line in lines:
            buffer += line
            try:
                parsed = list(
                    csv.reader(
                        io.StringIO(buffer, newline=""),
                        delimiter=",",
                        quotechar='"',
                        doublequote=True,
                        skipinitialspace=False,
                        strict=True,
                    )
                )
            except csv.Error:
                continue

            if parsed:
                records.extend(list(record) for record in parsed)
                buffer = ""

        if buffer:
            try:
                parsed = list(
                    csv.reader(
                        io.StringIO(buffer, newline=""),
                        delimiter=",",
                        quotechar='"',
                        doublequote=True,
                        skipinitialspace=False,
                        strict=False,
                    )
                )
                records.extend(list(record) for record in parsed)
            except csv.Error:
                records.append(buffer.rstrip("\r\n").split(","))

        return records


def _is_blank(record: List[str]) -> bool:
    return not record or all(value.strip() == "" for value in record)


def _header_score(record: List[str]) -> int:
    score = 0
    for value in record:
        text = value.strip()
        if not text:
            continue
        if re.search(r"[A-Za-z]", text):
            score += 2
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_ .()/&-]*", text):
            score += 2
        if re.fullmatch(r"[-+]?\d+(?:[.,]\d+)?", text):
            score -= 3
        if re.match(r"^\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}$", text):
            score -= 3
        if "://" in text or len(text) > 100:
            score -= 2
    score += len(set(value.strip().lower() for value in record if value.strip()))
    return score


def _find_header(records: List[List[str]], width: int) -> int:
    candidates = [i for i, record in enumerate(records) if len(record) == width]
    if not candidates:
        return 0

    for index in candidates:
        following: List[List[str]] = []
        for record in records[index + 1:]:
            if _is_blank(record):
                continue
            following.append(record)
            if len(following) == 4:
                break

        required = min(2, len(following))
        if required and sum(len(record) == width for record in following) >= required:
            if _header_score(records[index]) >= width * 3:
                return index

    return max(candidates, key=lambda i: (_header_score(records[i]), -i))


def _normalize_record(record: List[str], width: int) -> List[str]:
    values = list(record)
    if len(values) < width:
        values.extend([""] * (width - len(values)))
    elif len(values) > width:
        values = values[:width - 1] + [",".join(values[width - 1:])]
    return values


def parse_csv(raw_csv: str) -> Union[str, Dict[str, List]]:
    expected_width = 9
    records = _read_records(raw_csv)

    if not records:
        return {"columns": [], "rows": []}

    header_index = _find_header(records, expected_width)
    header = _normalize_record(records[header_index], expected_width)
    columns = [value.strip() for value in header]

    rows: List[List[str]] = []
    for record in records[header_index + 1:]:
        if _is_blank(record):
            continue
        normalized = _normalize_record(record, expected_width)
        if [value.strip() for value in normalized] == columns:
            continue
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
